ClientScript:Pointage Journalier Form.script:
frappe.ui.form.on('Pointage Journalier', {
  setup(frm) {
    // Picker ouvrier : actifs seulement (tous chantiers — un renfort d'un
    // autre chantier reste pointable, Kimi D2.2). Le pré-remplissage couvre
    // le chantier de la feuille.
    frm.set_query('ouvrier', 'lignes', () => ({filters: {actif: 1}}));
  },
  refresh(frm) {
    if (frm.is_new()) return;
    const val = frappe.user.has_role('ETRAPH Chef de Projet') || frappe.user.has_role('System Manager');
    const st = frm.doc.statut_validation;
    if (st === 'En attente') {
      frm.add_custom_button(__('Pré-remplir les ouvriers'), () => {
        frappe.call({method: 'etraph_theme.pointage.preremplir', args: {name: frm.doc.name}})
          .then(r => { frappe.show_alert(__('{0} ouvrier(s) ajouté(s)', [r.message.ajouts])); frm.reload_doc(); });
      });
      if (val) {
        frm.add_custom_button(__('✓ Valider'), () => {
          frappe.call({method: 'etraph_theme.pointage.valider_pointage', args: {name: frm.doc.name}})
            .then(() => frm.reload_doc());
        }).addClass('btn-primary');
      }
    }
    if (val && (st === 'En attente' || st === 'Validé')) {
      frm.add_custom_button(__('Annuler (motif)'), () => {
        frappe.prompt({fieldname: 'motif', fieldtype: 'Small Text', label: __('Motif'), reqd: 1}, v => {
          frappe.call({method: 'etraph_theme.pointage.annuler_pointage', args: {name: frm.doc.name, motif: v.motif}})
            .then(() => frm.reload_doc());
        }, __('Annulation'));
      });
    }
  }
});

ClientScript:Pointage Journalier List.script:
frappe.listview_settings['Pointage Journalier'] = frappe.listview_settings['Pointage Journalier'] || {};
frappe.listview_settings['Pointage Journalier'].onload = function(listview) {
  const val = frappe.user.has_role('ETRAPH Chef de Projet') || frappe.user.has_role('System Manager');
  if (!val) return;
  listview.page.add_inner_button(__('Tout valider'), () => {
    frappe.confirm(__('Valider TOUTES les feuilles en attente ?'), () => {
      frappe.call({method: 'etraph_theme.pointage.valider_lot'})
        .then(r => { frappe.show_alert(__('{0} feuille(s) validée(s)', [r.message.valides])); listview.refresh(); });
    });
  });
};
